{"implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_by_id = {}
    children = {}
    for node in nodes:
        node_id = node['id']
        node_by_id[node_id] = node
        children[node_id] = []
    for node in nodes:
        parent = node['parent']
        if parent is not None:
            children[parent].append(node['id'])
    root_id = None
    for node in nodes:
        if node['parent'] is None:
            root_id = node['id']
            break
    retained_ids = set(node['id'] for node in nodes)
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed_ids = []
    for node in sorted_nodes:
        nid = node['id']
        if nid == root_id:
            continue
        if node['symbol'] in required_symbols:
            continue
        if not node['removable']:
            continue
        has_retained_child = False
        for child_id in children.get(nid, []):
            if child_id in retained_ids:
                has_retained_child = True
                break
        if has_retained_child:
            continue
        retained_ids.remove(nid)
        removed_ids.append(nid)
    retained_sorted = sorted(retained_ids)
    return {
        'removed_node_ids': removed_ids,
        'retained_node_ids': retained_sorted
    }
"}
